// === Tab: mySketch ===
// 板ポリ芸です
// 参考：https://www.shadertoy.com/view/4lc3Wn
// じゃないかも？
// eddyさんの作品：https://neort.io/art/cglfrtcn70rvflp1r4h0?index=7&origin=latest
// ですね
// 別に↑が作りたいわけではないです。念のため。

// --------------------------------------------------------------------- //

// まず格子を用意するみたいです？TAUを6個くらいに分割して
// rは無限で
// めんどくさ
// (x,y)あるでしょ
// lengthと偏角を取り出して
// rがy軸で偏角がx軸なわけですけど
// たとえばy=xだとしてこれと(TAU,0)との距離ですが
// これを等分して。6等分とか？というか6分の1が「単位」ですね。
// この単位で距離を割って整数部分や小数部分であれこれやらかすってわけ
// 8等分でもいいけど
// 偶数の方がいいかな
// 2増えるたびにリセットするとループになる
// そんな感じかなぁ。

// atanって-3.14～3.14なので3.14を足しましょうかね
// ついでに正規化
// y=axのaと、これとの距離を偶数いくつで割るか、ですが。
// 向きの付いた距離です。aは正の数で、y=axの下側の時正の数。
// (ax-y)/sqrt(a*a+1)がそれ。これを...
// a*x-yとaでいいみたいですねぇ

// ただどっちも距離として解釈しないとわかりづらいですから。
// float d = (a*x-y)/sqrt(a*a+1.0);
// float d0 = a/sqrt(a*a+1.0);
// (d/d0)*6.0なので、ね。

// で、これを反対でやる。
// y=-axでいいと思う。この場合上に来るときに正とする。と？
// (ax+y)/aか～
// あとは？ていうかこれでいいの？？？
// しらねーよ

// x+=で0とx-=で1が同じ挙動。あとは...
// って感じなんですが、どうでしょう？

// yを0.25乗したらうまくいきました。なるほど～
// あとは境界をぼかすために
// fractのところを2.0倍して1.0を引いて1.57でも掛けてcosのイメージで

// 境界ぼかせるならsmoothはもはや不要だわね

// evenoddじゃないですか本家が。
// そうしましょうよ。

// 全画面にするためにaspect比をつかいましょう

// セルごとに色を変えてみました
// 異なるテクスチャを配しても面白そうですね？
// あなたの仕事です！！

let myShader;
const vs =
`
attribute vec3 aPosition;
uniform float uAspect;
varying vec2 vUv;
void main(){
  vUv = aPosition.xy * 2.0; // 今回は±1～±1で。
	vUv.x *= uAspect; // 全画面対応
  gl_Position = vec4(aPosition * 2.0, 1.0);
}
`;

const fs =
`
precision mediump float;
varying vec2 vUv;
uniform float uTime;
uniform sampler2D uRandom;

const float PI = 3.14159;

// hsb2rgb.
vec3 hsb2rgb(float h, float s, float b){
  vec3 c = vec3(h, s, b);
  vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
  rgb = rgb * rgb * (3.0 - 2.0 * rgb);
  return c.z * mix(vec3(1.0), rgb, c.y);
}

vec4 getColor(float x, float y, float power){
  x -= uTime*0.1;

  float x0 = x - fract(uTime*0.125);
  float x1 = x + fract(uTime*0.125);

  float value0 = (x0 + y)*12.0;
  float value1 = (x1 - y)*12.0;

	float n0 = mod(floor(value0), 12.0) / 12.0;
	float n1 = mod(floor(value1), 12.0) / 12.0;

	float phase = 0.5 * texture2D(uRandom, vec2(n0, n1)).r;
  float alpha = pow(max(sin(PI*value0)*sin(PI*value1), 0.0), power); // こんなもんですかね

  float r = length(vUv);
  vec3 baseColor = hsb2rgb(fract(uTime*0.1 + phase), r*0.707, 2.0*pow(r*0.707, 0.5));
  return vec4(baseColor, alpha);
}

void main(){
  float y = length(vUv);
  float x = (atan(vUv.y, vUv.x) + 3.14159) / 6.28318;
	// ちょっとしたトリックを追加
	y *= 1.0+0.25*sin(12.0*3.14159*x+uTime);
  y=pow(y, 0.25); // ここをいじるとおかしくなる。

	// これ以降のx,yに対する計算をメソッド化
  vec4 col1 = getColor(x, y, 0.25);
	vec4 col2 = getColor(x+0.015, y+0.03, 0.3);
	vec4 col3 = getColor(x+0.03, y+0.06, 0.35);
	col1 *= 0.8;
	col2 *= 0.6;
	col3 *= 0.4;
	// col2の上にcol1を重ねる
	vec4 col = col3;
	col.rgb = (1.0 - col2.a)*col.rgb + col2.a * col2.rgb;
	col.a = col.a + col2.a - col.a * col2.a;
	col.rgb = (1.0 - col1.a)*col.rgb + col1.a * col1.rgb;
	col.a = col.a + col1.a - col.a * col1.a;

  gl_FragColor = col * vec4(vec3(col.a), 1.0);
}
`;

let rdm;
function preload(){
	rdm = loadImage("https://inaridarkfox4231.github.io/assets/texture/rdm.png");
}

function setup() {
  createCanvas(4/3*windowHeight, windowHeight, WEBGL);
  shader(myShader = createShader(vs, fs));
  pixelDensity(1);
}

function draw() {
  background(0);
  myShader.setUniform("uTime", millis()/1000);
	myShader.setUniform("uAspect", width/height);
	myShader.setUniform("uRandom", rdm);
  plane(0);
}

